#!/usr/bin/env python3
"""drug/mutation_panel_screen — auto-generated run.py (archetype=drug).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "drug"
BRAIN = "drug"
SKILL = "mutation_panel_screen"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'mutation_panel_screen', 'n_compounds': 0, 'best_score': 0.0, 'compound_csv': '', 'diagnostics': {'brain': 'drug', 'archetype': 'drug'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """突变扫描:对 receptor 上一组 mutation,逐 mutant 用 vina 重 dock,看 affinity 变化。
    简化版:接受 mutant_receptors (list of pdb) — 不真做突变,只 dock。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    wt_pdb = payload.get("wt_receptor_pdb")
    mutants = payload.get("mutant_receptors") or []
    ligand = payload.get("ligand_sdf") or payload.get("ligand")
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="mut_panel_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "n_mutants": len(mutants), "out_dir": out_dir}

    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "wt_affinity": 0.0, "results": [],
                "n_compounds": 0, "diagnostics": {**diagnostics, "dry": True}}
    if not wt_pdb or not _os.path.isfile(wt_pdb):
        return {"ok": False, "error": "需要 wt_receptor_pdb", "diagnostics": diagnostics}
    if not ligand or not _os.path.isfile(ligand):
        return {"ok": False, "error": "需要 ligand_sdf", "diagnostics": diagnostics}

    def _dock_one(rec, tag):
        out_sdf = _os.path.join(out_dir, f"{tag}.sdf")
        r = run_tool(["vina", "--receptor", rec, "--ligand", ligand, "--autobox_ligand", ligand,
                      "--exhaustiveness", "8", "--num_modes", "5", "--out", out_sdf], timeout=600)
        if not r["ok"]:
            return None, r.get("error", "vina fail")
        for ln in r["stdout"].splitlines():
            parts = ln.split()
            if len(parts) >= 4 and parts[0] == "1":
                try:
                    return float(parts[1]), None
                except ValueError:
                    continue
        return None, "parse_fail"

    t0 = _time.time()
    wt_aff, wt_err = _dock_one(wt_pdb, "wt")
    results = []
    for m in mutants:
        if not _os.path.isfile(m):
            results.append({"mutant_pdb": m, "affinity": None, "delta_vs_wt": None, "error": "missing"}); continue
        aff, err = _dock_one(m, _os.path.basename(m).split(".")[0])
        delta = (aff - wt_aff) if (aff is not None and wt_aff is not None) else None
        results.append({"mutant_pdb": m, "affinity": aff, "delta_vs_wt": delta, "error": err})
    return {"ok": True, "skill_id": SKILL,
            "wt_receptor": wt_pdb, "wt_affinity": wt_aff,
            "results": results, "n_compounds": len(results),
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
